/*
 * A328833  A276085 applied to the intersection of A048103 (p^p-free numbers)
 *          and A276156 (sums of distinct primorials).
 * https://oeis.org/A328833
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = A276085(A328832(n)); A328832 = sums of distinct
 *            primorials with no p^p factor (generated by subset-sum
 *            enumeration), A276085(m) = Sum_{p^e || m} e * (product of primes
 *            < p)
 * Range:     u8 n <= 7, u16 n <= 7, u32 n <= 7, u64 n <= 13, u128 n <= 13,
 *            big any n
 * Validated: standard, pass, 34 terms through n = 34 (2026-11-08)
 * Helpers:   build_primes_upto, factor_u64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stddef.h>
#include "../utils/build_primes_upto.h"
#include "../utils/factor_u64.h"

static uint64_t *g_terms = NULL;
static size_t g_terms_cnt = 0;

static int cmp_u64_328833(const void *x, const void *y)
{
    uint64_t p = *(const uint64_t *)x, q = *(const uint64_t *)y;
    return (p < q) ? -1 : (p > q) ? 1 : 0;
}

static void init_terms_328833(void)
{
    static const uint64_t prim[16] = {
        1ULL, 2ULL, 6ULL, 30ULL, 210ULL, 2310ULL, 30030ULL, 510510ULL,
        9699690ULL, 223092870ULL, 6469693230ULL, 200560490190ULL,
        7420738134810ULL, 304250263527210ULL, 13082761331670030ULL,
        614889782588491410ULL
    };
    static const uint64_t bad[6] = {
        4ULL, 27ULL, 3125ULL, 823543ULL, 285311670611ULL, 302875106592253ULL
    };
    size_t total = (size_t)1 << 16;
    uint64_t *sums = (uint64_t *)malloc(total * sizeof(uint64_t));
    uint64_t *valid = (uint64_t *)malloc(total * sizeof(uint64_t));
    size_t cnt = 0;
    sums[0] = 0;
    size_t cur = 1;
    for (int i = 0; i < 16; ++i) {
        size_t c = cur;
        for (size_t j = 0; j < c; ++j)
            sums[cur++] = sums[j] + prim[i];
    }
    for (size_t j = 1; j < cur; ++j) {
        uint64_t v = sums[j];
        bool isbad = false;
        for (int b = 0; b < 6; ++b) {
            if (v % bad[b] == 0) { isbad = true; break; }
        }
        if (!isbad) valid[cnt++] = v;
    }
    qsort(valid, cnt, sizeof(uint64_t), cmp_u64_328833);
    size_t u = 0;
    for (size_t j = 0; j < cnt; ++j)
        if (j == 0 || valid[j] != valid[j - 1]) valid[u++] = valid[j];
    free(sums);
    g_terms = valid;
    g_terms_cnt = u;
}

seq_t a(idx_t n)
{
    if (!g_terms) init_terms_328833();
    if (n < 1 || (size_t)n > g_terms_cnt) return (seq_t)0;
    uint64_t m = g_terms[n - 1];
    if (m <= 1) return (seq_t)0;

    uint64_t facs[64];
    uint64_t exps[64];
    size_t fcnt = 0;
    factor_u64(m, facs, exps, &fcnt);

    uint64_t max_p = 0;
    for (size_t i = 0; i < fcnt; ++i)
        if (facs[i] > max_p) max_p = facs[i];

    uint64_t *plist = NULL;
    size_t pcnt = 0;
    build_primes_upto(max_p, &plist, &pcnt);

    seq_t result = 0;
    for (size_t i = 0; i < fcnt; ++i) {
        seq_t prod = 1;
        for (size_t k = 0; k < pcnt && plist[k] < facs[i]; ++k)
            prod = prod * (seq_t)plist[k];
        result += (seq_t)exps[i] * prod;
    }
    free(plist);
    return result;
}
